import type { Library, LibraryBullet } from '@bf/db/seed';
import data from './bullets.json';

/**
 * The offline bullet library.
 *
 * Generated by `pnpm seed` from the same CSVs that produce `seed.sql`, so the
 * library works with no backend and cannot drift from the database. Every row
 * carries the manufacturer page it was transcribed from, and none is marked
 * verified — that is a human act recorded against an account.
 */
const library = data as Library;

export const BULLETS: readonly LibraryBullet[] = library.bullets;
export const LIBRARY_GENERATED_AT = library.generatedAt;

export type { LibraryBullet };

/** Common calibre names, derived from the data rather than hard-coded. */
export function calibreOptions(): { value: string; label: string }[] {
  const diameters = [...new Set(BULLETS.map((bullet) => bullet.diameterIn))].sort((a, b) => a - b);
  return diameters.map((diameter) => ({
    value: diameter.toFixed(3),
    label: `${diameter.toFixed(3)} in`,
  }));
}

export function manufacturerOptions(): { value: string; label: string }[] {
  return [...new Set(BULLETS.map((bullet) => bullet.manufacturer))]
    .sort((a, b) => a.localeCompare(b))
    .map((name) => ({ value: name, label: name }));
}

export interface LibraryFilter {
  readonly query?: string;
  readonly diameterIn?: string;
  readonly manufacturer?: string;
  readonly bcType?: 'G1' | 'G7';
  readonly minWeightGr?: number;
  readonly maxWeightGr?: number;
}

/**
 * Filter the library.
 *
 * Search matches the manufacturer and the bullet name on whole words in any
 * order, so "eld 140" and "140 eld" both find the same row.
 */
export function searchBullets(filter: LibraryFilter): LibraryBullet[] {
  const terms = (filter.query ?? '')
    .toLowerCase()
    .split(/\s+/)
    .filter((term) => term !== '');

  return BULLETS.filter((bullet) => {
    if (filter.diameterIn !== undefined && bullet.diameterIn.toFixed(3) !== filter.diameterIn) {
      return false;
    }
    if (filter.manufacturer !== undefined && bullet.manufacturer !== filter.manufacturer) {
      return false;
    }
    if (filter.bcType === 'G1' && bullet.bcG1 === null) return false;
    if (filter.bcType === 'G7' && bullet.bcG7 === null) return false;
    if (filter.minWeightGr !== undefined && bullet.weightGr < filter.minWeightGr) return false;
    if (filter.maxWeightGr !== undefined && bullet.weightGr > filter.maxWeightGr) return false;

    if (terms.length === 0) return true;
    const haystack = `${bullet.manufacturer} ${bullet.name}`.toLowerCase();
    return terms.every((term) => haystack.includes(term));
  });
}

export function findBullet(id: string): LibraryBullet | null {
  return BULLETS.find((bullet) => bullet.id === id) ?? null;
}

/** The BC the solver should use, preferring G7 where the maker publishes one. */
export function preferredBc(bullet: LibraryBullet): { type: 'G1' | 'G7'; value: number } | null {
  if (bullet.bcG7 !== null) return { type: 'G7', value: bullet.bcG7 };
  if (bullet.bcG1 !== null) return { type: 'G1', value: bullet.bcG1 };
  return null;
}
